mapper.select:
select S.student_no as studentNo, S.account_no as accountNo, A.account_name as studentName, A.account_phone as studentPhone, A.account_id as studentEmail, S.student_school as studentSchool, S.student_grade as studentGrade, S.student_gender as studentGender, S.student_etc as studentEtc, S.student_academic_status as studentAcademicStatus,
-- 출석률 서브쿼리 (JOIN으로 전체 세션과 출석 세션을 한 방에 계산) NVL(( select case when count(CS.session_no) = 0 THEN 0 else round((count(ATT.attendance_no) / count(CS.session_no)) * 100) end from student_course SC inner join schedule Sch on SC.course_no = Sch.course_no inner join class_session CS on Sch.schedule_no = CS.schedule_no -- 출석 테이블은 left join (출석 안 했으면 count 안 되도록) left join attendance ATT on CS.session_no = ATT.class_session_no and ATT.student_no = SC.student_no and ATT.attendance_state = '출석' where SC.student_no = S.student_no and SC.student_course_status IN ('수강중', '수강완료') ), 0) AS attendanceRate
from student S inner join account A on S.account_no = A.account_no where S.student_no = #{studentNo}

mapper.update:
update student 
set student_academic_status = '재원' 
where student_no = #{studentNo}

mapper.select:
select s.*
from student s 
join account a on s.account_no = a.account_no
where a.account_phone = #{studentPhone}
  and s.student_no = #{studentNo}

select student_grade 
from student 
where student_no = #{studentNo}
